package com.fasterxml.jackson.databind.deser.impl;

import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.databind.DeserializationContext;
import com.fasterxml.jackson.databind.DeserializationFeature;
import com.fasterxml.jackson.databind.JsonDeserializer;
import com.fasterxml.jackson.databind.JsonMappingException;
import com.fasterxml.jackson.databind.deser.SettableBeanProperty;
import com.fasterxml.jackson.databind.util.NameTransformer;
import java.io.*;
import java.io.IOException;
import java.lang.reflect.InvocationTargetException;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collection;
import java.util.NoSuchElementException;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class BeanPropertyMap_remove_TriageGen0Test {

    private SettableBeanProperty prop1;
    private SettableBeanProperty prop2;
    private SettableBeanProperty prop3;

    @Before
    public void setUp() {
        prop1 = mock(SettableBeanProperty.class);
        prop2 = mock(SettableBeanProperty.class);
        prop3 = mock(SettableBeanProperty.class);

        when(prop1.getName()).thenReturn("name1");
        when(prop2.getName()).thenReturn("name2");
        when(prop3.getName()).thenReturn("name3");
    }

    @Test
    public void testRemove_Success() {
        Collection<SettableBeanProperty> props = new ArrayList<>(Arrays.asList(prop1, prop2, prop3));
        BeanPropertyMap map = BeanPropertyMap.construct(props, false);

        assertEquals(3, map.size());

        // Remove the middle property
        map.remove(prop2);

        assertEquals(2, map.size());
        assertNull(map.find("name2"));
        assertNotNull(map.find("name1"));
        assertNotNull(map.find("name3"));
    }

    @Test
    public void testRemove_FirstProperty() {
        Collection<SettableBeanProperty> props = new ArrayList<>(Arrays.asList(prop1, prop2));
        BeanPropertyMap map = BeanPropertyMap.construct(props, false);

        map.remove(prop1);

        assertEquals(1, map.size());
        assertNull(map.find("name1"));
        assertNotNull(map.find("name2"));
    }

    @Test
    public void testRemove_LastProperty() {
        Collection<SettableBeanProperty> props = new ArrayList<>(Arrays.asList(prop1, prop2));
        BeanPropertyMap map = BeanPropertyMap.construct(props, false);

        map.remove(prop2);

        assertEquals(1, map.size());
        assertNotNull(map.find("name1"));
        assertNull(map.find("name2"));
    }

    @Test(expected = NoSuchElementException.class)
    public void testRemove_NotFound() {
        Collection<SettableBeanProperty> props = new ArrayList<>(Arrays.asList(prop1, prop2));
        BeanPropertyMap map = BeanPropertyMap.construct(props, false);

        // prop3 is not in the map
        map.remove(prop3);
    }

    @Test
    public void testRemove_WithNullInHashArea() {
        // This test targets the 'if (prop == null) continue;' branch.
        // Since we use the static construct method, we simulate a scenario where 
        // the internal structure might have nulls if we were manipulating it via reflection,
        // but for standard unit testing, we ensure the loop handles the existing properties correctly.

        Collection<SettableBeanProperty> props = new ArrayList<>(Arrays.asList(prop1, prop2));
        BeanPropertyMap map = BeanPropertyMap.construct(props, false);

        // Ensure logic works when skipping items (simulated by the internal loop logic)
        map.remove(prop1);
        assertEquals(1, map.size());
        assertNull(map.find("name1"));
    }

    @Test
    public void testRemove_CaseInsensitiveMatch() {
        // The code notes that it checks the name slot. 
        // If caseInsensitive is true, the key comparison logic depends on getPropertyName.
        Collection<SettableBeanProperty> props = new ArrayList<>(Arrays.asList(prop1));
        BeanPropertyMap map = BeanPropertyMap.construct(props, true);

        // Create a dummy property with same name but different instance to trigger the search logic
        SettableBeanProperty propMatch = mock(SettableBeanProperty.class);
        when(propMatch.getName()).thenReturn("name1");

        map.remove(propMatch);

        assertEquals(0, map.size());
    }
}
